/*	parser for yacc output	*/

var (
	pgDebug        = 0
	pgErrorVerbose = false
)

type pgLexer interface {
	Lex(lval *pgSymType) int
	Error(s string)
}

type pgParser interface {
	Parse(pgLexer) int
	Lookahead() int
}

type pgParserImpl struct {
	lval  pgSymType
	stack [pgInitialStackSize]pgSymType
	char  int
}

func (p *pgParserImpl) Lookahead() int {
	return p.char
}

func pgNewParser() pgParser {
	return &pgParserImpl{}
}

const pgFlag = -1000

func pgTokname(c int) string {
	if c >= 1 && c-1 < len(pgToknames) {
		if pgToknames[c-1] != "" {
			return pgToknames[c-1]
		}
	}
	return __yyfmt__.Sprintf("tok-%v", c)
}

